    30	
    31	    public void registerRoutes(Javalin app) {
    32	        app.get("/rooms", this::getRooms);
    33	        app.post("/reservations", this::createReservation);
    34	        app.get("/reservations/{id}", this::getReservation);
    35	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
    36	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
    37	        app.post("/reservations/{id}/check-in", this::checkIn);
    38	        app.post("/reservations/{id}/check-out", this::checkOut);
    39	        app.get("/reservations/{id}/document", this::getDocument);
    40	        app.get("/messages", this::getMessages);
    41	        app.get("/reports/occupancy", this::getOccupancyReport);
    42	        app.get("/reports/revenue", this::getRevenueReport);
    43	
    44	        app.exception(InvalidRequestException.class, (e, ctx) -> {
    45	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    46	        });
    47	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
    48	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
    49	        });
    50	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
    51	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    52	        });
    53	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
    54	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
    55	        });
    56	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
    57	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
    58	        });
    59	        app.exception(CapacityExceededException.class, (e, ctx) -> {
    60	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
    61	        });
    62	        app.exception(IllegalArgumentException.class, (e, ctx) -> {
    63	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    64	        });
    65	        app.exception(DateTimeParseException.class, (e, ctx) -> {
    66	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    67	        });
    68	    }
    69	
    70	    private void getRooms(Context ctx) {
    71	        List<Room> rooms = roomRepository.findAll();
    72	        ctx.json(rooms.stream().map(RoomResponse::from).toList());
    73	    }
    74	
    75	    private void createReservation(Context ctx) {
    76	        try {
    77	            ReservationRequest request = ctx.bodyAsClass(ReservationRequest.class);
    78	
    79	            if (request.roomNumber() == null || request.guestName() == null ||
    80	                request.guestEmail() == null || request.guestCpf() == null ||
    81	                request.checkIn() == null || request.checkOut() == null ||
    82	                request.guests() == null || request.ratePlan() == null) {
    83	                throw new InvalidRequestException("Missing required fields");
    84	            }
    85	
    86	            Reservation reservation = new Reservation();
    87	            reservation.setRoomNumber(request.roomNumber());
    88	            reservation.setGuestName(request.guestName());
    89	            reservation.setGuestEmail(request.guestEmail());
    90	            reservation.setGuestCpf(request.guestCpf());
    91	            reservation.setCheckIn(request.checkIn());
    92	            reservation.setCheckOut(request.checkOut());
    93	            reservation.setGuests(request.guests());
    94	            reservation.setRatePlan(request.ratePlan());
    95	            reservation.setCompanyCode(request.companyCode());
    96	
    97	            Reservation created = reservationService.createReservation(reservation);
    98	            ctx.status(201).json(ReservationResponse.from(created));
    99	        } catch (Exception e) {
   100	            if (e instanceof InvalidRequestException ||
   101	                e instanceof RoomNotFoundException ||
   102	                e instanceof RoomUnavailableException ||
   103	                e instanceof CapacityExceededException ||
   104	                e instanceof IllegalArgumentException) {
   105	                throw e;
   106	            }
   107	            throw new InvalidRequestException("Invalid request: " + e.getMessage());
   108	        }
   109	    }
   110	
   111	    private void getReservation(Context ctx) {
   112	        Long id = ctx.pathParamAsClass("id", Long.class).get();
   113	        Reservation reservation = reservationService.getReservation(id);
   114	        ctx.json(ReservationResponse.from(reservation));
   115	    }
   116	
   117	    private void confirmReservation(Context ctx) {
   118	        Long id = ctx.pathParamAsClass("id", Long.class).get();
   119	        Reservation reservation = reservationService.confirmReservation(id);
   120	        ctx.json(ReservationResponse.from(reservation));
   121	    }
   122	
   123	    private void cancelReservation(Context ctx) {
   124	        Long id = ctx.pathParamAsClass("id", Long.class).get();
   125	        Reservation reservation = reservationService.cancelReservation(id);
   126	        ctx.json(ReservationResponse.from(reservation));
   127	    }
   128	
   129	    private void checkIn(Context ctx) {
   130	        Long id = ctx.pathParamAsClass("id", Long.class).get();
   131	        Reservation reservation = reservationService.checkIn(id);
   132	        ctx.json(ReservationResponse.from(reservation));
   133	    }
   134	
   135	    private void checkOut(Context ctx) {
   136	        Long id = ctx.pathParamAsClass("id", Long.class).get();
   137	        Reservation reservation = reservationService.checkOut(id);
   138	        ctx.json(DocumentResponse.from(reservation));
   139	    }
   140	
   141	    private void getDocument(Context ctx) {
   142	        Long id = ctx.pathParamAsClass("id", Long.class).get();
   143	        Reservation reservation = reservationService.getReservation(id);
   144	
   145	        if (!reservation.isPaid()) {
   146	            throw new OperationNotAllowedException("Document only available for paid reservations");
   147	        }
   148	
   149	        ctx.json(DocumentResponse.from(reservation));
   150	    }
   151	
   152	    private void getMessages(Context ctx) {
   153	        List<Message> messages = messageRepository.findAll();
   154	        ctx.json(messages.stream().map(MessageResponse::from).toList());
   155	    }
   156	
   157	    private void getOccupancyReport(Context ctx) {
   158	        String dateParam = ctx.queryParam("date");
   159	        if (dateParam == null) {
   160	            throw new InvalidRequestException("Missing date parameter");
   161	        }
   162	
   163	        LocalDate date = LocalDate.parse(dateParam);
   164	        String csv = reportService.generateOccupancyReport(date);
   165	
   166	        ctx.contentType("text/csv; charset=utf-8").result(csv);
   167	    }
   168	
   169	    private void getRevenueReport(Context ctx) {
   170	        String monthParam = ctx.queryParam("month");
   171	        if (monthParam == null) {
   172	            throw new InvalidRequestException("Missing month parameter");
   173	        }
   174	
   175	        YearMonth month = YearMonth.parse(monthParam);
   176	        String csv = reportService.generateRevenueReport(month);
   177	
   178	        ctx.contentType("text/csv; charset=utf-8").result(csv);
   179	    }
   180	}
