    22	) {
    23	    public static DocumentResponse from(Reservation r) {
    24	        return new DocumentResponse(
    25	            "Comprovante de reserva",
    26	            r.getId(),
    27	            r.getGuestName(),
    28	            r.getGuestCpf(),
    29	            r.getRoomNumber(),
    30	            getRoomTypeName(r.getRoomNumber()),
    31	            r.getCheckIn(),
