    40	    private static String getRoomTypeName(String roomNumber) {
    41	        return switch (roomNumber) {
    42	            case "101", "102" -> "STANDARD";
    43	            case "201", "202" -> "DELUXE";
    44	            case "301" -> "SUITE";
    45	            default -> "UNKNOWN";
    46	        };
    47	    }
