     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.*;
     4	
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.DayOfWeek;
     8	import java.time.LocalDate;
     9	import java.time.Month;
    10	import java.util.Map;
    11	
    12	public class PricingService {
    13	
    14	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    15	    private static final Map<String, BigDecimal> CORPORATE_DISCOUNTS = Map.of(
    16	        "TECNOSUL", new BigDecimal("0.12"),
    17	        "AGROVALE", new BigDecimal("0.18"),
    18	        "FARMAVIDA", new BigDecimal("0.25")
    19	    );
    20	    private static final Map<RoomType, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
    21	        RoomType.STANDARD, new BigDecimal("520.00"),
    22	        RoomType.DELUXE, new BigDecimal("820.00"),
    23	        RoomType.SUITE, new BigDecimal("1200.00")
    24	    );
    25	
    26	    public void calculatePricing(Reservation reservation, Room room) {
    27	        int nights = (int) reservation.getCheckIn().datesUntil(reservation.getCheckOut()).count();
    28	        reservation.setNights(nights);
    29	
    30	        switch (reservation.getRatePlan()) {
    31	            case WEEKEND_PACKAGE -> calculateWeekendPackage(reservation, room);
    32	            case CORPORATE -> calculateCorporate(reservation, room);
    33	            case LONG_STAY -> calculateLongStay(reservation, room);
    34	            case NON_REFUNDABLE -> calculateNonRefundable(reservation, room);
    35	            default -> calculateStandard(reservation, room);
    36	        }
    37	    }
    38	
    39	    private void calculateStandard(Reservation reservation, Room room) {
    40	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
    41	        reservation.setSubtotal(subtotal);
    42	        reservation.setDiscount(BigDecimal.ZERO);
    43	        reservation.setTotal(subtotal);
    44	    }
    45	
    46	    private void calculateNonRefundable(Reservation reservation, Room room) {
    47	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
    48	        reservation.setSubtotal(subtotal);
    49	
    50	        BigDecimal discount = subtotal.multiply(new BigDecimal("0.15"));
    51	        discount = roundHalfToEven(discount);
    52	        reservation.setDiscount(discount);
    53	
    54	        BigDecimal total = subtotal.subtract(discount);
    55	        reservation.setTotal(total);
    56	    }
    57	
    58	    private void calculateCorporate(Reservation reservation, Room room) {
    59	        String companyCode = reservation.getCompanyCode();
    60	        if (companyCode == null || !CORPORATE_DISCOUNTS.containsKey(companyCode)) {
    61	            throw new IllegalArgumentException("Invalid company code for corporate rate plan");
    62	        }
    63	
    64	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
    65	        reservation.setSubtotal(subtotal);
    66	
    67	        BigDecimal discountRate = CORPORATE_DISCOUNTS.get(companyCode);
    68	        BigDecimal discount = subtotal.multiply(discountRate);
    69	        discount = roundHalfToEven(discount);
    70	        reservation.setDiscount(discount);
    71	
    72	        BigDecimal total = subtotal.subtract(discount);
    73	        reservation.setTotal(total);
    74	    }
    75	
    76	    private void calculateWeekendPackage(Reservation reservation, Room room) {
    77	        if (reservation.getNights() != 2) {
    78	            throw new IllegalArgumentException("Weekend package requires exactly 2 nights");
    79	        }
    80	
    81	        LocalDate checkIn = reservation.getCheckIn();
    82	        LocalDate checkOut = reservation.getCheckOut();
    83	
    84	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY || checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    85	            throw new IllegalArgumentException("Weekend package must be Friday to Sunday");
    86	        }
    87	
    88	        BigDecimal packagePrice = WEEKEND_PACKAGE_PRICES.get(room.getType());
    89	        reservation.setSubtotal(packagePrice);
    90	        reservation.setDiscount(BigDecimal.ZERO);
    91	        reservation.setTotal(packagePrice);
    92	    }
    93	
    94	    private void calculateLongStay(Reservation reservation, Room room) {
    95	        if (reservation.getNights() < 7) {
    96	            throw new IllegalArgumentException("Long stay requires at least 7 nights");
    97	        }
    98	
    99	        BigDecimal subtotal = calculateSubtotal(reservation, room.getNightlyRate());
   100	        reservation.setSubtotal(subtotal);
   101	
   102	        BigDecimal discount = subtotal.multiply(new BigDecimal("0.10"));
   103	        discount = roundHalfToEven(discount);
   104	        reservation.setDiscount(discount);
   105	
   106	        BigDecimal total = subtotal.subtract(discount);
   107	        reservation.setTotal(total);
   108	    }
   109	
   110	    private BigDecimal calculateSubtotal(Reservation reservation, BigDecimal baseRate) {
   111	        BigDecimal subtotal = BigDecimal.ZERO;
   112	
   113	        LocalDate date = reservation.getCheckIn();
   114	        while (date.isBefore(reservation.getCheckOut())) {
   115	            BigDecimal nightRate = baseRate;
   116	            if (isHighSeason(date)) {
   117	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER);
   118	                nightRate = roundHalfToEven(nightRate);
   119	            }
   120	            subtotal = subtotal.add(nightRate);
   121	            date = date.plusDays(1);
   122	        }
   123	
   124	        return roundHalfToEven(subtotal);
   125	    }
   126	
   127	    private boolean isHighSeason(LocalDate date) {
   128	        Month month = date.getMonth();
   129	        int day = date.getDayOfMonth();
   130	
   131	        if (month == Month.JULY) {
   132	            return true;
   133	        }
   134	
   135	        if (month == Month.DECEMBER && day >= 15) {
   136	            return true;
   137	        }
   138	
   139	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
   140	            return true;
   141	        }
   142	
   143	        return false;
   144	    }
   145	
   146	    public BigDecimal calculateRefund(Reservation reservation) {
   147	        if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
   148	            return BigDecimal.ZERO;
   149	        }
   150	
   151	        BigDecimal refundAmount = switch (reservation.getRatePlan()) {
   152	            case NON_REFUNDABLE -> BigDecimal.ZERO;
   153	            case WEEKEND_PACKAGE -> {
   154	                BigDecimal half = reservation.getAmountPaid().divide(new BigDecimal("2"), 10, RoundingMode.HALF_EVEN);
   155	                yield roundHalfToEven(half);
   156	            }
   157	            default -> reservation.getAmountPaid();
   158	        };
   159	
   160	        return refundAmount;
   161	    }
   162	
   163	    private BigDecimal roundHalfToEven(BigDecimal value) {
   164	        return value.setScale(2, RoundingMode.HALF_EVEN);
   165	    }
   166	}
